const (
	shardCount   = 1000    // 哈希分片数量
	progressStep = 1000000 // 每100万行打印进度
)

func diffFilesWithProgress(fileA, fileB, fileC string) error {
	startTime := time.Now()
	tmpDir, err := os.MkdirTemp("", "filediff")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	fmt.Printf("开始处理，创建临时分片目录: %s\n", tmpDir)

	// 阶段1: 处理文件B到分片
	if err := processFileToShards(fileB, tmpDir, "b"); err != nil {
		return err
	}
	fmt.Printf("文件B分片完成 [耗时: %v]\n", time.Since(startTime))

	// 阶段2: 处理文件A并输出差异
	if err := processFileA(fileA, fileC, tmpDir); err != nil {
		return err
	}

	totalTime := time.Since(startTime)
	fmt.Printf("\n处理完成! 总耗时: %v\n", totalTime)
	return nil
}

func processFileToShards(filePath, tmpDir, prefix string) error {
	shardFiles := make([]*os.File, shardCount)
	for i := range shardFiles {
		f, err := os.Create(filepath.Join(tmpDir, fmt.Sprintf("%s_shard_%d.tmp", prefix, i)))
		if err != nil {
			return err
		}
		defer f.Close()
		shardFiles[i] = f
	}

	file, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	lineCount := 0
	for scanner.Scan() {
		line := scanner.Text()
		shardIdx := hash(line) % shardCount
		if _, err := shardFiles[shardIdx].WriteString(line + "\n"); err != nil {
			return err
		}

		lineCount++
		if lineCount%progressStep == 0 {
			fmt.Printf("已处理 %s: %d 万行\n", filePath, lineCount/10000)
		}
	}
	fmt.Printf("文件 %s 处理完成，共 %d 行\n", filePath, lineCount)
	return scanner.Err()
}

func processFileA(fileA, fileC, tmpDir string) error {
	aFile, err := os.Open(fileA)
	if err != nil {
		return err
	}
	defer aFile.Close()

	cFile, err := os.Create(fileC)
	if err != nil {
		return err
	}
	defer cFile.Close()

	writer := bufio.NewWriterSize(cFile, 8*1024*1024) // 8MB缓冲
	defer writer.Flush()

	scanner := bufio.NewScanner(aFile)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	lineCount := 0
	shardCache := make(map[int]map[string]bool) // 分片缓存
	var mu sync.Mutex

	for scanner.Scan() {
		line := scanner.Text()
		shardIdx := int(hash(line) % shardCount)

		// 按需加载分片
		mu.Lock()
		if _, loaded := shardCache[shardIdx]; !loaded {
			if err := loadShard(tmpDir, shardIdx, shardCache); err != nil {
				mu.Unlock()
				return err
			}
		}
		exists := shardCache[shardIdx][line]
		mu.Unlock()

		if !exists {
			if _, err := writer.WriteString(line + "\n"); err != nil {
				return err
			}
		}

		lineCount++
		if lineCount%progressStep == 0 {
			fmt.Printf("处理文件A: 已比较 %d 万行 [差异行: %d]\n", lineCount/10000, lineCount-len(shardCache)*50000)
		}
	}

	fmt.Printf("文件A处理完成，共 %d 行\n", lineCount)
	return scanner.Err()
}

func loadShard(tmpDir string, shardIdx int, cache map[int]map[string]bool) error {
	file, err := os.Open(filepath.Join(tmpDir, fmt.Sprintf("b_shard_%d.tmp", shardIdx)))
	if err != nil {
		return err
	}
	defer file.Close()

	cache[shardIdx] = make(map[string]bool)
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		cache[shardIdx][scanner.Text()] = true
	}
	return scanner.Err()
}

func hash(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}

// HandleNoQaData 处理缺少QA数据的链接信息
//
// 从给定的文件中读取缺少QA数据的链接列表，并发查询这些链接的QA信息并回写到数据库
//
// 参数:
//
//	ctx: 上下文对象
//	noQaFile: 包含缺少QA数据的链接文件路径
//	diffCount: 预期处理的链接数量
//
// 返回值:
//
//	error: 处理过程中遇到的错误，nil表示成功
func (a *BacktrackPanLinkInfo) HandleNoQaData(ctx context.Context) error {
	file, err := os.Open(noQaFile)
	if err != nil {
		return err
	}
	defer file.Close()

	const batchSize = 100
	scanner := bufio.NewScanner(file)
	shortLinks := make([]string, 0, batchSize)
	getQALimit := rate.NewLimiter(2, 1) // 限流2qps
	successTotal := 0

	for scanner.Scan() {
		// 每100行处理一次
		line := scanner.Text()
		shortLinks = append(shortLinks, line)

		if len(shortLinks) == batchSize {
			successBatch, err := a.GetQaAndWriteBackToMongo(ctx, shortLinks, getQALimit)
			if err != nil {
				a.Logger().Warning(ctx, "GetQaAndWriteBackToMongo error", logit.Error("err", err))
			}
			successTotal += successBatch
			shortLinks = shortLinks[:0]
		}
	}
	if len(shortLinks) > 0 {
		successBatch, err := a.GetQaAndWriteBackToMongo(ctx, shortLinks, getQALimit)
		if err != nil {
			fmt.Println("GetQaAndWriteBackToMongo error:", err)
			a.Logger().Warning(ctx, "GetQaAndWriteBackToMongo error", logit.Error("err", err))
		}
		successTotal += successBatch
	}
	if err := scanner.Err(); err != nil {
		return err
	}
	// 发送如流消息
	msgContent := fmt.Sprintf("回溯任务[backtrack_pan_link_info] 查询QA数据并回写MongoDB完成，成功数量：%d", successTotal)
	alarmService := alarm.NewHiAlarm(InfoflowRobotToken)
	err = alarmService.SendMsg(InfoflowGroup, msgContent)
	if err != nil {
		a.Logger().Warning(ctx, "sendHiMsg err", logit.Error("Err", err))
	}
	fmt.Println("任务[backtrack_pan_link_info] QA处理完成，成功数量：", successTotal)
	return nil
}

func (a *BacktrackPanLinkInfo) GetQaAndWriteBackToMongo(ctx context.Context, shortLinks []string, getQALimit *rate.Limiter) (int, error) {
	fmt.Println(ctx, "GetQaAndWriteBackToMongo start")
	successCount := 0

	// 查询starlink_pan_link_info信息
	fieldsOfPanLink := "short_url,long_url,link_status,display_name"
	condition := map[string]any{
		"short_url": map[string]any{"$in": shortLinks},
	}
	linkInfoListOfProcess := make([]*mongoEntities.PanLinkInfo, 0, len(shortLinks))
	err := resource.AladdinMongo.QueryMongo(ctx, mongoEntities.CollectionPanLinkInfo, condition, fieldsOfPanLink, "", int64(len(shortLinks)), 0, &linkInfoListOfProcess)
	if err != nil {
		return successCount, err
	}

	// 请求策略查询qa，回写starlink_link_qa
	pg := gtask.Group{
		Concurrent:    10,
		AllowSomeFail: true,
	}
	for _, item := range linkInfoListOfProcess {
		linkInfo := item
		_ = pg.Run(func() error {
			// 限流,避免挤压线上例行任务
			if err := getQALimit.Wait(ctx); err != nil {
				return err
			}
			//过滤网盘链接中缺少提取码的资源

			if !panLinkRege.MatchString(linkInfo.LongURL) {
				return nil
			}

			// todo:识别网盘空链接，过滤

			err := getQAForOneLink(ctx, linkInfo)
			if err != nil {
				fmt.Println("GetQAForOneLink error:", err)
				a.Logger().Warning(ctx, "GetQAForOneLink error", logit.Error("Err", err))
				return err
			}
			return nil
		})
	}
	successCount, err = pg.Wait()
	return successCount, nil
}

// HandleNotProduceData 处理未生产数据的链接重推待生产集合
//
// 函数读取指定文件中的短链接列表，对每个链接进行以下处理：
// 1. 从MongoDB查询资源标题信息
// 2. 检查标题是否在黑名单中
// 3. 若非黑名单内容，将资源推入待生产集合
//
// 参数:
//
//	ctx: 上下文对象，用于请求超时控制等
//
// 返回:
//
//	error: 处理过程中发生的错误，若成功返回nil
func (a *BacktrackPanLinkInfo) HandleNotProduceData(ctx context.Context) error {
	file, err := os.Open("/home/work/se/baidu/ps-aladdin/plugin-task/diffbuild_test.data")
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	const batch = 100
	shortLinks := make([]string, 0, batch)
	var produceLimit = rate.NewLimiter(10, 1) // 限流10qps
	successTotal := 0
	for scanner.Scan() {
		// 每100行处理一次
		line := scanner.Text()
		shortLinks = append(shortLinks, line)
		if len(shortLinks) == batch {
			successBatch, err := a.PushPendingToProduce(ctx, shortLinks, produceLimit)
			if err != nil {
				a.Logger().Warning(ctx, "PushPendingToProduce error", logit.Error("err", err))
			}
			successTotal += successBatch
			shortLinks = shortLinks[:0]
		}
	}
	if len(shortLinks) > 0 {
		successBatch, err := a.PushPendingToProduce(ctx, shortLinks, produceLimit)
		if err != nil {
			fmt.Println("PushPendingToProduce error", err)
			a.Logger().Warning(ctx, "PushPendingToProduce error", logit.Error("err", err))
		}
		successTotal += successBatch
	}
	if err := scanner.Err(); err != nil {
		return err
	}
	// 发送如流消息
	msgContent := fmt.Sprintf("回溯任务[backtrack_pan_link_info] 推送待生产集合成功数量：%d", successTotal)
	alarmService := alarm.NewHiAlarm(InfoflowRobotToken)
	err = alarmService.SendMsg(InfoflowGroup, msgContent)
	if err != nil {
		a.Logger().Warning(ctx, "sendHiMsg err", logit.Error("Err", err))
	}
	fmt.Println("任务[backtrack_pan_link_info] 待生产集合处理完成，成功数量：", successTotal)
	return nil
}

func (a *BacktrackPanLinkInfo) PushPendingToProduce(ctx context.Context, linkList []string, produceLimit *rate.Limiter) (int, error) {
	fmt.Println("PushPendingToProduce start")
	successCount := 0

	//查询黑名单
	blackKeywordCondition := map[string]any{
		"status": 1,
	}
	blackKeywordList, err := mongoDao.GetAllBlackKeywords(ctx, blackKeywordCondition)
	if err != nil {
		a.Logger().Warning(ctx, "GetNormalizedBlackKeywords", logit.Error("Err", err))
		return successCount, err
	}
	blackKeywordMap := make(map[string]string, len(blackKeywordList))
	for _, black := range blackKeywordList {
		blackKeywordMap[strings.ToLower(black)] = black
	}

	pg := gtask.Group{
		Concurrent:    10,
		AllowSomeFail: true,
	}
	for _, shortURL := range linkList {
		_ = pg.Run(func() error {
			// 查starlink_resource_title获取title
			condition := map[string]any{
				"short_link": shortURL,
			}
			resourceTitleInfoList := make([]*mongoEntities.ResourceTitleInfo, 0, 1)
			queryMongoErr := resource.AladdinMongo.QueryMongo(ctx, mongoEntities.CollectionResourceTitle, condition, "", "@id", 1, 0, &resourceTitleInfoList)
			if queryMongoErr != nil {
				return queryMongoErr
			}
			if len(resourceTitleInfoList) == 0 {
				return fmt.Errorf("empty resource info, short link: %s", shortURL)
			}
			resourceTitleInfo := resourceTitleInfoList[0]

			// title过黑名单
			title := strings.ToLower(resourceTitleInfo.Title)
			if _, ok := blackKeywordMap[title]; ok {
				return fmt.Errorf("black keyword, short link: %s", shortURL)
			}

			// 查starlink_pan_link_info检查分享文件状态
			conditionLink := map[string]any{
				"short_url":   shortURL,
				"link_status": 1,
			}
			panLinkInfoList := make([]*mongoEntities.PanLinkInfo, 0, 1)
			err := resource.AladdinMongo.QueryMongo(ctx, mongoEntities.CollectionPanLinkInfo, conditionLink, "", "", 1, 0, &panLinkInfoList)
			if err != nil {
				return err
			}
			if len(panLinkInfoList) > 0 {
				linkInfo := panLinkInfoList[0]
				if linkInfo.DisplayName == "该分享文件已过期" || linkInfo.FileSuffix == "无法访问" {
					return fmt.Errorf("invalid resource status, short link: %s", shortURL)
				}
			}
			// todo 查link_qa, 如果没有qa对应，推到待生产集合也无法生产成功，过滤掉

			// 推入待生产集合,限流10qps
			if err := produceLimit.Wait(ctx); err != nil {
				fmt.Println("wwwwwwwww")
				return err
			}
			tsk := &PendingToProduce{Helper: task.NewTaskHelper()}
			err = tsk.WriteToPendingCollection(ctx, resourceTitleInfo)
			if err != nil {
				fmt.Println("WriteToPendingCollection err:", err)
				a.Logger().Warning(ctx, "WriteToPendingCollection err", logit.Error("Err", err))
				return err
			}
			return nil
		})
	}
	successCount, err = pg.Wait()
	return successCount, err
}

